# -*- coding: utf-8 -*-
"""例句拆解（Zergliederung）。参考 FlashCard 的 trans.py，但按德语重做。

主轨是「顺读」：德→中逐块、每块标成分，按德语原序读下去。
德语特色：
  - Satzklammer 句框：情态动词 / 可分动词 / Perfekt 三种情形下，
    变位动词占第二位，动词第二部分被挤到句末——用 klammer 画出这个框。
  - 名词短语标注格（Nominativ / Akkusativ / Dativ），这是中文里没有的范畴。
  - 完整译文按成分着色，让读者看出每段中文来自哪个德语意群。

键 = 官方例句原文（与词表逐字一致，构建期校验）。
字段：
  zh      完整中文翻译
  pat     句型标签
  flow    [德块, 中文块, 成分] —— 按德语原序；拼接回原句由构建期校验
  klammer 可选 [框前, 框左动词, 框中成分, 框右动词第二部分, 类型]
          type ∈ modal(情态) | trennbar(可分) | perfekt(Perfekt)
  kasus   可选 [德语短语, 格]
  final   可选 [中文块, 成分] —— 完整译文；缺省用 zh
  tip     一句话点破

成分代号：s 主语 · v 变位动词 · v2 动词第二部分 · a 状语 · o 宾语 ·
          d 定语 · c 从句 · x 默认
"""
